/*B"H — collapsed rails become clean neon handles, not crushed panels */
.is-collapsed,
.is-detached {
  min-width: 58px !important;
  width: 58px !important;
  max-width: 58px !important;
  overflow: hidden !important;
  border-radius: 22px !important;
}
.is-collapsed > :not(.panel-topbar),
.is-detached > :not(.panel-topbar) { display: none !important; }
.is-collapsed .panel-topbar,
.is-detached .panel-topbar {
  height: 100%;
  min-height: 0;
  display: grid;
  grid-template-rows: minmax(0, 1fr) 46px;
  grid-template-columns: 1fr;
  align-items: center;
  justify-items: center;
  gap: 8px;
  padding: 10px 7px;
  border-bottom: 0;
  cursor: pointer;
  outline: none;
  background:
    radial-gradient(circle at 50% 8%, rgba(34,211,238,.22), transparent 35%),
    linear-gradient(180deg, rgba(15,23,42,.94), rgba(2,6,23,.98));
}
.is-collapsed .panel-title,
.is-detached .panel-title {
  display: block;
  writing-mode: vertical-rl;
  text-orientation: mixed;
  transform: rotate(180deg);
  max-height: 100%;
  max-width: 100%;
  overflow: hidden;
  white-space: nowrap;
  font-size: .78rem;
  opacity: .92;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.is-collapsed .panel-actions,
.is-detached .panel-actions {
  grid-row: 2;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  background: transparent;
}
.is-collapsed .panel-actions [data-panel-action="fullscreen"],
.is-detached .panel-actions [data-panel-action="fullscreen"] { display: none !important; }
.is-collapsed .panel-actions button,
.is-detached .panel-actions button {
  width: 40px;
  height: 40px;
  border-radius: 16px;
  background: linear-gradient(135deg, rgba(14,165,233,.24), rgba(168,85,247,.22)), rgba(2,6,23,.9);
  box-shadow: 0 0 24px rgba(34,211,238,.16), inset 0 1px 0 rgba(255,255,255,.08);
}
.is-collapsed .panel-topbar:hover,
.is-detached .panel-topbar:hover,
.is-collapsed .panel-topbar:focus-visible,
.is-detached .panel-topbar:focus-visible {
  box-shadow: inset 0 0 0 2px var(--ai-border-hot), 0 0 30px rgba(45, 212, 255, .20);
}
.is-detached {
  position: relative !important;
  z-index: auto !important;
  resize: none !important;
}
